# frozen_string_literal: true

require "openssl"
require "rails_helper"

RSpec.describe "Razorpay webhook billing fence signature order", type: :request do
  it "rejects a bad Razorpay signature with 401 during a handoff before the fence" do
    company = create(:india_company, base_currency: "INR")
    client = create(:client, company:, currency: "INR", name: "Acme", email: "client@example.com")
    invoice = create(
      :invoice,
      company:,
      client:,
      currency: "INR",
      amount: 1000,
      amount_due: 1000,
      amount_paid: 0,
      status: "sent",
      payment_infos: {
        "razorpay_payment_link_id" => "plink_fence_123",
        "razorpay_payment_link_url" => "https://rzp.io/rzp/fence"
      }
    )
    create(
      :payments_provider,
      company:,
      name: PaymentsProvider::RAZORPAY_PROVIDER,
      enabled: true,
      connected: true,
      settings: {
        key_id: "rzp_test_123",
        key_secret: "secret",
        webhook_secret: "webhook_secret",
        enabled_on_invoices: true
      }
    )
    payload = {
      event: "payment_link.paid",
      created_at: Time.zone.local(2026, 4, 29, 12, 0, 0).to_i,
      payload: {
        payment_link: {
          entity: {
            id: "plink_fence_123",
            amount_paid: 100_000,
            updated_at: Time.zone.local(2026, 4, 29, 12, 0, 0).to_i,
            reference_id: "miru-inv-#{invoice.id}",
            notes: { miru_invoice_id: invoice.id.to_s, company_id: company.id.to_s },
            customer: { name: "Acme" }
          }
        },
        payment: { entity: { id: "pay_fence_123" } }
      }
    }.to_json
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update!(handoff_step: "close_admission")

    post "/webhooks/razorpay/payment_links", params: payload, headers: {
      "CONTENT_TYPE" => "application/json",
      "HTTP_X_RAZORPAY_SIGNATURE" => "bad"
    }

    # The signature is the webhook's trust boundary, so an unsigned caller
    # learns nothing about a handoff and gets the same 401 as without one.
    expect(response).to have_http_status(:unauthorized)
    expect(response.body).not_to include("ownership_moving")
    expect(invoice.reload).not_to be_paid
    expect(Payment.count).to eq(0)
  end
end

RSpec.describe "Provider payment webhooks refused during a handoff", type: :request do
  let(:company) { create(:india_company, base_currency: "INR") }
  let(:client) { create(:client, company:, currency: "INR", name: "Acme") }

  it "answers a signed Razorpay payment-link event with a retryable 503, not 500, and records no payment" do
    invoice = create(
      :invoice, company:, client:, currency: "INR", amount: 1000, amount_due: 1000, amount_paid: 0, status: "sent",
      payment_infos: { "razorpay_payment_link_id" => "plink_fence_signed", "razorpay_payment_link_url" => "https://rzp.io/rzp/signed" }
    )
    create(
      :payments_provider, company:, name: PaymentsProvider::RAZORPAY_PROVIDER, enabled: true, connected: true,
      settings: { key_id: "rzp_test_123", key_secret: "secret", webhook_secret: "webhook_secret", enabled_on_invoices: true }
    )
    payload = {
      event: "payment_link.paid",
      created_at: Time.zone.local(2026, 4, 29, 12, 0, 0).to_i,
      payload: {
        payment_link: {
          entity: {
            id: "plink_fence_signed",
            amount_paid: 100_000,
            updated_at: Time.zone.local(2026, 4, 29, 12, 0, 0).to_i,
            reference_id: "miru-inv-#{invoice.id}",
            notes: { miru_invoice_id: invoice.id.to_s, company_id: company.id.to_s },
            customer: { name: "Acme" }
          }
        },
        payment: { entity: { id: "pay_fence_signed" } }
      }
    }.to_json
    TimekeepingOwnership.current.update!(handoff_step: "close_admission")

    post "/webhooks/razorpay/payment_links", params: payload, headers: {
      "CONTENT_TYPE" => "application/json",
      "HTTP_X_RAZORPAY_SIGNATURE" => OpenSSL::HMAC.hexdigest("SHA256", "webhook_secret", payload)
    }

    expect(response).to have_http_status(:service_unavailable)
    expect(response.parsed_body["reason"]).to eq("ownership_moving")
    expect(response.headers["Retry-After"]).to eq("5")
    expect(Payment.where(invoice_id: invoice.id).count).to eq(0)
    expect(invoice.reload).not_to be_paid
  end

  it "lets a Stripe checkout-expired event escape the fence without writing a failed payment row" do
    invoice = create(:invoice, company:, client:, status: "sent")
    event = OpenStruct.new(
      created: Time.current.to_i,
      data: OpenStruct.new(
        object: OpenStruct.new(metadata: OpenStruct.new(invoice_id: invoice.id), amount_total: 10_000, currency: "inr")
      )
    )
    TimekeepingOwnership.current.update!(handoff_step: "close_admission")

    expect { InvoicePayment::StripeCheckoutFailed.process(event) }
      .to raise_error(Timekeeping::BillingFence::OwnershipMoving)
    expect(Payment.where(invoice_id: invoice.id).count).to eq(0)
  end
end
